// Host plugin: the `image_gen` tool.
//
// DSH has no image generation of its own. This row adds exactly one model-facing
// tool and calls whatever OpenAI-compatible images API the user configures:
// `/images/generations` for a new image, `/images/edits` (multipart) when
// reference images are supplied. The endpoint and credential reference may be
// borrowed from an LLM provider already configured in DSH, so a gateway does not
// need to be entered twice. The generated bytes are written under the configured
// output directory, and — when the session's model route declares `image` input —
// also committed to the attachment store so the picture enters model context and
// the Web UI can show it beside the call.
//
// A call may run in the foreground or as a `ctx.jobs` background task. The
// background path returns a job id immediately and keeps the same generation,
// download, disk and attachment work, so `job_output` sees the saved paths.
//
// The feature's on/off switch is the profile row's own: disabling
// `extra-image-gen` in the 「插件」 page disposes the fiber and the tool
// registration with it, which is what removes `image_gen` from the model's tool
// list. Nothing is registered at a broader scope.
//
// The settings namespace is the profile entry id (equal to the exported `name`),
// and every field is `.volatile()`, so an edit commits into the live fiber and
// the next call uses it without restarting the Host.
//
// Credentials are references, never literals: `apiKeyEnv` names a credential
// (or an environment variable) that `ctx.credentials` resolves at call time, the
// same path official provider rows use. A deployment that needs no key (a local
// gateway) can leave it unsupplied.

import { mkdir, readFile, stat, writeFile } from 'node:fs/promises'
import { randomBytes } from 'node:crypto'
import { homedir } from 'node:os'
import { basename, isAbsolute, join, resolve } from 'node:path'
import Schema from '@deepseek-ai/schemastery'
import { defineTool } from '@deepseek-ai/dsh-tools'
import { resolveDshHome } from '../shared/dsh-home.mjs'
import {
  IMAGE_GEN_NAMESPACE,
  MAX_DOWNLOAD_BYTES,
  TOOL_NAME,
  detectImageMediaType,
  fetchImageBytes,
  imageFileName,
  normalizeImageRefs,
  requestImageAPI,
  resolveImageEntry,
  resolveMode,
} from './model.mjs'
import { resolveImageEndpoint } from './providers.mjs'

export const name = IMAGE_GEN_NAMESPACE

/** The tool registers into `ctx.tools`; everything else is optional at runtime. */
export const inject = ['tools']

export const Config = Schema.object({
  provider: Schema.string().default('')
    .description('Configured LLM provider whose endpoint and credential this tool reuses; empty uses the manual fields below')
    .volatile(),
  baseURL: Schema.string().default('https://api.openai.com/v1')
    .description('Manual OpenAI-compatible base URL used only when no provider is selected')
    .volatile(),
  apiKeyEnv: Schema.string().role('credential-ref').default('IMAGE_API_KEY')
    .description('Manual credential reference used only when no provider is selected; empty for gateways that need none')
    .volatile(),
  model: Schema.string().default('')
    .description('Image model id sent as `model`; the tool reports a configuration error until this is set')
    .volatile(),
  endpoint: Schema.union(['generate', 'edit']).default('generate')
    .description('Endpoint used when a call brings no reference image and names no mode')
    .volatile(),
  size: Schema.string().default('')
    .description('Default `size` for every call; empty omits the field')
    .volatile(),
  quality: Schema.string().default('')
    .description('Default `quality` for every call; empty omits the field')
    .volatile(),
  outputDir: Schema.string().default('')
    .description('Directory for saved images; empty uses <DSH_HOME>/generated-images, a relative path resolves against the session cwd')
    .volatile(),
  timeoutMs: Schema.number().min(1000).default(120000)
    .description('Abort one provider request after this many milliseconds')
    .volatile(),
})

/** An AbortError-shaped failure for a cancelled foreground/background call. */
function abortError() {
  const error = new Error('image generation aborted')
  error.name = 'AbortError'
  return error
}

/** The session's working directory, used to resolve relative reference and output paths. */
function sessionCwd(exec) {
  const cwd = exec?.agent?.session?.header?.cwd
  return typeof cwd === 'string' && cwd !== '' ? cwd : process.cwd()
}

/**
 * Resolve the directory generated images land in.
 *
 * An empty setting is a real default rather than "no output": images go under
 * the harness home, where the attachment store already lives and where a profile
 * reset does not take them with it. `~` is expanded because the settings field is
 * a plain text box, and a relative path follows the session cwd so a model
 * working in a project gets the image next to the project instead of inside the
 * application directory.
 *
 * @param ctx - plugin context, for the harness home accessor.
 * @param configured - the `outputDir` setting.
 * @param exec - current tool execution, for the session cwd.
 * @returns the absolute output directory.
 */
function outputDirectory(ctx, configured, exec) {
  const value = typeof configured === 'string' ? configured.trim() : ''
  if (value === '') return join(resolveDshHome(ctx), 'generated-images')
  if (value === '~') return homedir()
  if (value.startsWith('~/') || value.startsWith('~\\')) return resolve(join(homedir(), value.slice(2)))
  if (isAbsolute(value)) return resolve(value)
  return resolve(sessionCwd(exec), value)
}

/**
 * Resolve the API key from credentials, then the process environment.
 *
 * `credentials` is consulted first because that is the supported store: its
 * local backend already falls back to the environment itself, and resolving
 * through it keeps the key out of this plugin's settings document. A blank
 * `apiKeyEnv` means "this gateway needs no key" and returns undefined, which is
 * different from a configured name that could not be resolved.
 *
 * @param ctx - plugin context.
 * @param configured - the `apiKeyEnv` setting.
 * @returns the key, undefined for the no-key case, or null when a named
 *   credential is missing.
 */
async function resolveApiKey(ctx, configured) {
  const envName = typeof configured === 'string' ? configured.trim() : ''
  if (envName === '') return undefined

  const credentials = ctx.get('credentials')
  if (credentials !== undefined && typeof credentials.resolve === 'function') {
    try {
      const resolved = await credentials.resolve(envName)
      if (typeof resolved?.value === 'string' && resolved.value !== '') return resolved.value
    } catch {
      // A missing credential store entry is reported below as a missing key; the
      // store's own error text is not more useful to the caller.
    }
  }
  const fromEnv = process.env[envName]
  if (typeof fromEnv === 'string' && fromEnv !== '') return fromEnv
  return null
}

/**
 * Load one reference image for the edit endpoint.
 *
 * Both a local path and an http(s) URL are accepted. The media type comes from
 * the bytes alone: the provider is about to receive this file, so a name, an
 * extension or a remote content-type is not evidence enough to upload it. Only
 * the four formats DSH can also store are admitted.
 *
 * @param ref - model-supplied path or URL.
 * @param signal - tool cancellation signal.
 * @param exec - current execution, for relative paths.
 * @returns the bytes, display name and media type.
 */
async function loadReferenceImage(ref, signal, exec) {
  if (/^https?:\/\//iu.test(ref)) {
    const bytes = await fetchImageBytes(fetch, ref, signal)
    const mediaType = detectImageMediaType(bytes)
    if (mediaType === undefined) throw new Error(`${TOOL_NAME}: 参考图必须是 PNG/JPEG/WebP/GIF：${ref}`)
    const declared = new URL(ref).pathname
    return { bytes, name: basename(declared) || 'reference', mediaType }
  }

  const path = isAbsolute(ref) ? ref : resolve(sessionCwd(exec), ref)
  let info
  try {
    info = await stat(path)
  } catch (error) {
    throw new Error(`${TOOL_NAME}: 读不到参考图 ${path}：${error instanceof Error ? error.message : String(error)}`)
  }
  if (!info.isFile()) throw new Error(`${TOOL_NAME}: 参考图不是文件：${path}`)
  if (info.size > MAX_DOWNLOAD_BYTES) throw new Error(`${TOOL_NAME}: 参考图超过 ${MAX_DOWNLOAD_BYTES} 字节上限：${path}`)
  const bytes = new Uint8Array(await readFile(path))
  const mediaType = detectImageMediaType(bytes)
  if (mediaType === undefined) throw new Error(`${TOOL_NAME}: 参考图必须是 PNG/JPEG/WebP/GIF：${path}`)
  return { bytes, name: basename(path), mediaType }
}

/**
 * Whether the calling route can accept an image block.
 *
 * A tool result with an image enters durable session history, and a text-only
 * route cannot continue past it. Unknown capability therefore degrades to
 * "path only" instead of risking the session; the file is saved either way.
 *
 * @param ctx - plugin context, for the optional `llm` service.
 * @param exec - current tool execution, carrying the calling agent.
 * @param signal - the generation's cancellation signal.
 * @returns whether an image block may be emitted.
 */
async function routeAcceptsImages(ctx, exec, signal = exec?.signal) {
  const llm = ctx.get('llm')
  if (llm === undefined || typeof llm.resolveModelInfo !== 'function') return false
  const routed = exec?.agent?.session?.requestHeader?.()?.config
  const provider = routed?.provider ?? exec?.agent?.options?.provider
  const model = routed?.model ?? exec?.agent?.options?.model
  if (typeof provider !== 'string' || typeof model !== 'string') return false
  try {
    const info = await llm.resolveModelInfo(provider, model, signal)
    return Array.isArray(info?.inputModalities) && info.inputModalities.includes('image')
  } catch {
    return false
  }
}

/**
 * Commit one saved image to the attachment store.
 * @param ctx - plugin context.
 * @param bytes - encoded image bytes.
 * @param mediaType - sniffed media type.
 * @param name - display name.
 * @returns the attachment reference, or undefined when no store is mounted or
 *   it refuses this format.
 */
async function attachImage(ctx, bytes, mediaType, name) {
  const attachments = ctx.get('attachments')
  if (attachments === undefined || typeof attachments.saveImage !== 'function') return undefined
  if (!Array.isArray(attachments.imageLimits?.mediaTypes) || !attachments.imageLimits.mediaTypes.includes(mediaType)) {
    return undefined
  }
  return attachments.saveImage({ data: bytes, mediaType, name })
}

/** Compress a prompt into one card line. */
function promptLine(prompt, limit = 80) {
  const first = String(prompt ?? '').replace(/\s+/gu, ' ').trim()
  return first.length > limit ? `${first.slice(0, limit)}…` : first
}

/** Render one saved image line for the model-facing text. */
function imageLine(image) {
  const width = image.attachment?.width ?? image.width
  const height = image.attachment?.height ?? image.height
  const facts = [
    image.mediaType,
    width !== undefined && height !== undefined ? `${width}x${height}` : undefined,
    `${image.bytes} 字节`,
  ].filter(value => value !== undefined)
  const suffix = facts.length === 0 ? '' : `（${facts.join('，')}）`
  const revised = image.revisedPrompt === undefined ? '' : `\n  修订后提示词：${image.revisedPrompt}`
  return `- ${image.path}${suffix}${revised}`
}

/** Render the model-facing text for one completed generation. */
function resultLines(value) {
  const lines = [
    `${TOOL_NAME} 已用 ${value.model} 通过 ${value.mode} 端点保存 ${value.images.length} 张图片：`,
    ...value.images.map(imageLine),
  ]
  if (value.warnings.length > 0) lines.push(`注意：${value.warnings.join('；')}`)
  return lines
}

/**
 * Run one image generation to completion.
 *
 * The tool's foreground path and its background job share this function; only
 * the cancellation signal differs. Keeping the API call, download, disk write
 * and attachment commit here means a background result is the same artifact a
 * foreground call would produce.
 *
 * @param ctx - plugin context.
 * @param config - live settings namespace.
 * @param args - validated tool arguments.
 * @param exec - the originating tool execution, for session cwd and agent facts.
 * @param outerSignal - cancellation from the caller or background job.
 * @returns the completed generation.
 */
async function generateImage(ctx, config, args, exec, outerSignal) {
  const model = String(config.model.get() ?? '').trim()
  if (model === '') {
    throw new Error(`${TOOL_NAME}: 生图模型未配置，请先在「设置 → 提示词与技能 → 图片生成」里填写模型`)
  }
  const prompt = String(args.prompt ?? '').trim()
  if (prompt === '') throw new Error(`${TOOL_NAME}: prompt 不能为空`)
  if (outerSignal?.aborted === true) {
    throw abortError()
  }

  const references = normalizeImageRefs(args.images)
  const maskRef = typeof args.mask === 'string' ? args.mask.trim() : ''
  const mode = resolveMode(args.mode, config.endpoint.get(), references.length + (maskRef === '' ? 0 : 1))
  if (mode === 'generate') {
    if (references.length > 0) throw new Error(`${TOOL_NAME}: generate 端点不接受 images，要编辑现有图片请用 edit 端点`)
    if (maskRef !== '') throw new Error(`${TOOL_NAME}: mask 只能用于 edit 端点`)
  }
  if (mode === 'edit' && references.length === 0) {
    throw new Error(`${TOOL_NAME}: edit 端点需要至少一张参考图，请通过 images 传入`)
  }

  let endpoint
  try {
    endpoint = resolveImageEndpoint(ctx, {
      provider: config.provider.get(),
      baseURL: config.baseURL.get(),
      apiKeyEnv: config.apiKeyEnv.get(),
    })
  } catch (error) {
    throw new Error(`${TOOL_NAME}: ${error instanceof Error ? error.message : String(error)}`)
  }

  const apiKey = await resolveApiKey(ctx, endpoint.apiKeyEnv)
  if (outerSignal?.aborted === true) {
    throw abortError()
  }
  if (apiKey === null) {
    const keyName = endpoint.apiKeyEnv
    throw new Error(`${TOOL_NAME}: 找不到凭据 ${keyName}，请在凭据或环境变量里配置，或把「密钥凭据名」留空`)
  }

  const timeoutMs = config.timeoutMs.get()
  const timeoutSignal = typeof AbortSignal.timeout === 'function' ? AbortSignal.timeout(timeoutMs) : undefined
  const signals = [outerSignal, timeoutSignal].filter(candidate => candidate !== undefined)
  const signal = signals.length === 0
    ? undefined
    : signals.length === 1
      ? signals[0]
      : typeof AbortSignal.any === 'function'
        ? AbortSignal.any(signals)
        : timeoutSignal ?? outerSignal

  try {
    const loadedReferences = []
    for (const reference of references) loadedReferences.push(await loadReferenceImage(reference, signal, exec))
    const loadedMask = maskRef === '' ? undefined : await loadReferenceImage(maskRef, signal, exec)

    const requested = await requestImageAPI({
      fetchImpl: fetch,
      baseURL: endpoint.baseURL,
      apiKey,
      model,
      mode,
      prompt,
      size: args.size ?? config.size.get(),
      quality: args.quality ?? config.quality.get(),
      n: args.n,
      images: loadedReferences,
      mask: loadedMask,
      signal,
    })

    const directory = outputDirectory(ctx, config.outputDir.get(), exec)
    await mkdir(directory, { recursive: true })

    const images = []
    const warnings = []
    const canAttach = await routeAcceptsImages(ctx, exec, signal)
    for (let index = 0; index < requested.entries.length; index += 1) {
      const resolved = await resolveImageEntry({
        fetchImpl: fetch,
        entry: requested.entries[index],
        signal,
        maxBytes: MAX_DOWNLOAD_BYTES,
      })
      const mediaType = detectImageMediaType(resolved.bytes)
      const fileName = imageFileName(new Date(), randomBytes(3).toString('hex'), index, mediaType)
      const path = join(directory, fileName)
      // `wx` refuses to overwrite: a filename collision must fail loudly rather
      // than replace an earlier picture.
      await writeFile(path, resolved.bytes, { flag: 'wx' })

      const image = {
        path,
        bytes: resolved.bytes.byteLength,
        ...mediaType === undefined ? {} : { mediaType },
        ...resolved.revisedPrompt === undefined ? {} : { revisedPrompt: resolved.revisedPrompt },
      }

      if (canAttach && mediaType !== undefined) {
        try {
          const ref = await attachImage(ctx, resolved.bytes, mediaType, fileName)
          if (ref !== undefined) {
            // Keep the store's own metadata: it is what a later read
            // validates against, and it can differ from the source file.
            image.attachment = {
              attachmentId: ref.attachmentId,
              mediaType: ref.mediaType,
              bytes: ref.bytes,
              width: ref.width,
              height: ref.height,
              name: ref.name ?? fileName,
            }
          }
        } catch (error) {
          // The file is already durable; a store that refuses this image
          // (size, pixel count) must not fail the generation itself.
          warnings.push(`第 ${index + 1} 张图片未能进入会话附件：${error instanceof Error ? error.message : String(error)}`)
        }
      }

      images.push(image)
    }

    return { mode: requested.mode, model: requested.model ?? model, images, warnings }
  } catch (error) {
    if (timeoutSignal?.aborted === true && outerSignal?.aborted !== true) {
      throw new Error(`${TOOL_NAME}: 请求超时（${timeoutMs} 毫秒）`)
    }
    throw error
  }
}

export function apply(ctx, config) {
  // One definition per fiber: the row's switch decides whether a fiber exists at
  // all, so there is no registration cycle to rebuild for.
  const tool = defineTool({
    name: TOOL_NAME,
    description: 'Generate a new image or edit existing images through the configured OpenAI-compatible image API, saving the result to disk. Pass `images` (local paths or http(s) URLs) to edit; without images the configured default endpoint is used (generate unless changed in settings). Set `run_in_background: true` for a long generation: the call returns a job id immediately; collect it with `job_output` and stop it with `job_kill`.',
    parameters: {
      prompt: {
        type: 'string',
        required: true,
        description: 'What the image should show, or the edit instruction when editing.',
      },
      mode: {
        type: 'string',
        enum: ['generate', 'edit'],
        description: 'Endpoint to use. Omitted: edit when `images` is present, otherwise the configured default.',
      },
      images: {
        type: 'array',
        items: { type: 'string' },
        description: 'Reference images to edit: absolute or session-relative paths, or http(s) URLs. Selects the edit endpoint when `mode` is omitted.',
      },
      mask: {
        type: 'string',
        description: 'Optional mask image for the edit endpoint, same forms as `images`.',
      },
      size: {
        type: 'string',
        description: 'Provider size such as 1024x1024; overrides the configured default when given.',
      },
      quality: {
        type: 'string',
        description: 'Provider quality such as high, medium or low; overrides the configured default when given.',
      },
      n: {
        type: 'integer',
        description: 'How many images to request; omitted sends one.',
      },
      run_in_background: {
        type: 'boolean',
        description: 'Run as a background job and return its job id immediately; collect with job_output or stop with job_kill. Defaults to false.',
      },
    },
    output: {
      schema: {
        oneOf: [
          {
            type: 'object',
            additionalProperties: false,
            properties: {
              jobId: { type: 'string', required: true },
            },
          },
          {
            type: 'object',
            additionalProperties: false,
            properties: {
              mode: { type: 'string', enum: ['generate', 'edit'], required: true },
              model: { type: 'string', required: true },
              images: {
                type: 'array',
                required: true,
                items: {
                  type: 'object',
                  additionalProperties: false,
                  properties: {
                    path: { type: 'string', required: true },
                    mediaType: { type: 'string', enum: ['image/png', 'image/jpeg', 'image/webp', 'image/gif'] },
                    bytes: { type: 'integer', required: true },
                    revisedPrompt: { type: 'string' },
                    attachment: {
                      type: 'object',
                      additionalProperties: false,
                      properties: {
                        attachmentId: { type: 'string', required: true },
                        mediaType: { type: 'string', enum: ['image/png', 'image/jpeg', 'image/webp', 'image/gif'], required: true },
                        bytes: { type: 'integer', required: true },
                        width: { type: 'integer' },
                        height: { type: 'integer' },
                        name: { type: 'string' },
                      },
                    },
                  },
                },
              },
              warnings: { type: 'array', required: true, items: { type: 'string' } },
            },
          },
        ],
      },
      render: (_args, value) => {
        if (typeof value.jobId === 'string') {
          return [{
            type: 'text',
            text: `started background ${TOOL_NAME} job ${value.jobId}; collect its result with job_output`,
          }]
        }
        const lines = resultLines(value)
        const blocks = [{ type: 'text', text: lines.join('\n') }]
        for (const image of value.images) {
          // The attachment store may re-encode a source image (GIF always,
          // oversized PNG/JPEG sometimes), so the block must carry the store's
          // own reference, never the source file's media type or byte count.
          if (image.attachment === undefined) continue
          blocks.push({ type: 'image', attachment: image.attachment })
        }
        return blocks
      },
    },
    async execute(args, exec) {
      const prompt = String(args.prompt ?? '').trim()
      if (prompt === '') throw new Error(`${TOOL_NAME}: prompt 不能为空`)
      const model = String(config.model.get() ?? '').trim()
      if (model === '') {
        throw new Error(`${TOOL_NAME}: 生图模型未配置，请先在「设置 → 提示词与技能 → 图片生成」里填写模型`)
      }

      if (args.run_in_background === true) {
        const jobs = ctx.get('jobs')
        if (jobs === undefined || typeof jobs.start !== 'function') {
          throw new Error(`${TOOL_NAME}: 后台任务不可用，请加载 @deepseek-ai/dsh-jobs 和 @deepseek-ai/dsh-tool-jobs`)
        }
        if (exec.signal?.aborted === true) {
          throw abortError()
        }
        const controller = new AbortController()
        const owner = exec.agent?.id
        const jobId = jobs.start({
          kind: 'image_gen',
          label: promptLine(prompt),
          ...owner === undefined ? {} : { owner },
          run: () => {
            const work = generateImage(ctx, config, args, exec, controller.signal)
            return {
              cancel: reason => controller.abort(reason ?? 'background image_gen task killed'),
              done: work.then(
                value => ({ status: 'completed', result: resultLines(value).join('\n') }),
                error => ({
                  status: controller.signal.aborted ? 'killed' : 'failed',
                  detail: error instanceof Error ? error.message : String(error),
                }),
              ),
            }
          },
        })
        return { jobId }
      }

      return generateImage(ctx, config, args, exec, exec.signal)
    },
    presentCall(args) {
      const preview = promptLine(args.prompt)
      const background = args.run_in_background === true
      return {
        card: 'generic',
        title: `${background ? 'Background image' : args.mode === 'edit' || (args.mode === undefined && (args.images?.length ?? 0) > 0) ? 'Edit image' : 'Generate image'}: ${preview}`,
        kind: 'other',
      }
    },
  })

  // Dies with the fiber — that disposal is exactly what the row's switch does.
  ctx.tools.register(tool)
}
